package controlplane

import(
	"bytes"
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/aonsyed/cyberpanel/platform/internal/federation"
)
const Schema=`
CREATE TABLE IF NOT EXISTS fleet_nodes(id TEXT PRIMARY KEY,owner_tenant_id TEXT NOT NULL,name TEXT NOT NULL,state TEXT NOT NULL,authority_epoch BIGINT NOT NULL,capabilities_json TEXT NOT NULL,projection_sequence BIGINT NOT NULL,snapshot_generation BIGINT NOT NULL,last_seen_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,certificate_fingerprint TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fleet_grants(id TEXT PRIMARY KEY,node_id TEXT NOT NULL,peer_id TEXT NOT NULL,authority_epoch BIGINT NOT NULL,state TEXT NOT NULL,grant_json TEXT NOT NULL,expires_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS fleet_grants_node_epoch ON fleet_grants(node_id,authority_epoch,state,expires_at);
CREATE TABLE IF NOT EXISTS fleet_intents(id TEXT PRIMARY KEY,node_id TEXT NOT NULL,owner_tenant_id TEXT NOT NULL,status TEXT NOT NULL,priority INTEGER NOT NULL,intent_json TEXT NOT NULL,receipt_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,expires_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS fleet_intents_node_queue ON fleet_intents(node_id,status,priority,created_at);
CREATE TABLE IF NOT EXISTS fleet_command_admissions(node_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_digest TEXT NOT NULL,intent_id TEXT NOT NULL UNIQUE,effect_id TEXT NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL,PRIMARY KEY(node_id,idempotency_key));
CREATE TABLE IF NOT EXISTS fleet_receipt_replays(node_id TEXT NOT NULL,receipt_digest TEXT NOT NULL,intent_id TEXT NOT NULL,signature_key_id TEXT NOT NULL,received_at TIMESTAMP NOT NULL,PRIMARY KEY(node_id,receipt_digest));
CREATE TABLE IF NOT EXISTS fleet_projections(node_id TEXT NOT NULL,tenant_id TEXT NOT NULL,resource_kind TEXT NOT NULL,resource_id TEXT NOT NULL,generation BIGINT NOT NULL,status_json TEXT NOT NULL,digest TEXT NOT NULL,observed_at TIMESTAMP NOT NULL,event_sequence BIGINT NOT NULL,stale INTEGER NOT NULL,PRIMARY KEY(node_id,resource_kind,resource_id));
CREATE TABLE IF NOT EXISTS fleet_events(node_id TEXT NOT NULL,sequence BIGINT NOT NULL,event_id TEXT NOT NULL,event_json TEXT NOT NULL,occurred_at TIMESTAMP NOT NULL,PRIMARY KEY(node_id,sequence),UNIQUE(node_id,event_id));
CREATE TABLE IF NOT EXISTS fleet_sagas(id TEXT PRIMARY KEY,owner_tenant_id TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,current_step INTEGER NOT NULL,saga_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,error_code TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fleet_encrypted_secrets(target_node_id TEXT NOT NULL,secret_id TEXT NOT NULL,version BIGINT NOT NULL,envelope_json TEXT NOT NULL,expires_at TIMESTAMP NOT NULL,consumed_at TIMESTAMP,PRIMARY KEY(target_node_id,secret_id,version));
CREATE TABLE IF NOT EXISTS fleet_revocations(node_id TEXT NOT NULL,authority_epoch BIGINT NOT NULL,status TEXT NOT NULL,revocation_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,PRIMARY KEY(node_id,authority_epoch));
`
type Store struct{db *sql.DB;clock func()time.Time}
func NewStore(db *sql.DB)(*Store,error){if db==nil{return nil,ErrInvalid};return &Store{db:db,clock:time.Now},nil}
func(s *Store)Bootstrap(ctx context.Context)error{_,err:=s.db.ExecContext(ctx,Schema);return err}
func(s *Store)PutNode(ctx context.Context,node Node)error{raw,_:=json.Marshal(node.Capabilities);_,err:=s.db.ExecContext(ctx,`INSERT INTO fleet_nodes VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,state=excluded.state,authority_epoch=excluded.authority_epoch,capabilities_json=excluded.capabilities_json,projection_sequence=excluded.projection_sequence,snapshot_generation=excluded.snapshot_generation,last_seen_at=excluded.last_seen_at,updated_at=excluded.updated_at,certificate_fingerprint=excluded.certificate_fingerprint`,node.ID,node.OwnerTenantID,node.Name,node.State,node.AuthorityEpoch,raw,node.ProjectionSequence,node.SnapshotGeneration,node.LastSeenAt,node.CreatedAt,node.UpdatedAt,node.CertificateFingerprint);return err}
func(s *Store)Node(ctx context.Context,id federation.ID)(Node,error){var node Node;var raw []byte;err:=s.db.QueryRowContext(ctx,`SELECT id,owner_tenant_id,name,state,authority_epoch,capabilities_json,projection_sequence,snapshot_generation,last_seen_at,created_at,updated_at,certificate_fingerprint FROM fleet_nodes WHERE id=?`,id).Scan(&node.ID,&node.OwnerTenantID,&node.Name,&node.State,&node.AuthorityEpoch,&raw,&node.ProjectionSequence,&node.SnapshotGeneration,&node.LastSeenAt,&node.CreatedAt,&node.UpdatedAt,&node.CertificateFingerprint);if errors.Is(err,sql.ErrNoRows){return node,ErrNotFound};if err!=nil{return node,err};err=json.Unmarshal(raw,&node.Capabilities);return node,err}
func(s *Store)PutGrant(ctx context.Context,grant federation.MutationGrant)error{if s==nil||ctx==nil||grant.Validate(s.clock().UTC())!=nil{return ErrInvalid};raw,err:=json.Marshal(grant);if err!=nil{return err};_,err=s.db.ExecContext(ctx,`INSERT INTO fleet_grants(id,node_id,peer_id,authority_epoch,state,grant_json,expires_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET state=excluded.state,grant_json=excluded.grant_json,expires_at=excluded.expires_at,updated_at=excluded.updated_at WHERE fleet_grants.node_id=excluded.node_id AND fleet_grants.peer_id=excluded.peer_id AND fleet_grants.authority_epoch=excluded.authority_epoch`,grant.ID,grant.NodeID,grant.PeerID,grant.AuthorityEpoch,"active",raw,grant.ExpiresAt,s.clock().UTC());return err}
func(s *Store)Grant(ctx context.Context,id federation.ID)(federation.MutationGrant,error){var grant federation.MutationGrant;var raw []byte;var state string;err:=s.db.QueryRowContext(ctx,`SELECT state,grant_json FROM fleet_grants WHERE id=?`,id).Scan(&state,&raw);if errors.Is(err,sql.ErrNoRows){return grant,ErrNotFound};if err!=nil{return grant,err};if state!="active"{return grant,ErrForbidden};if err=json.Unmarshal(raw,&grant);err!=nil{return grant,err};return grant,nil}
func(s *Store)QueueIntent(ctx context.Context,owner federation.ID,intent federation.Intent,priority uint8,requestDigest string)(federation.Intent,bool,error){if s==nil||ctx==nil||!owner.Valid()||!intent.ID.Valid()||!intent.NodeID.Valid()||intent.IdempotencyKey==""||intent.EffectID==""||!validSHA256(requestDigest){return federation.Intent{},false,ErrInvalid};raw,err:=json.Marshal(intent);if err!=nil{return federation.Intent{},false,err};tx,err:=s.db.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{return federation.Intent{},false,err};defer tx.Rollback();result,err:=tx.ExecContext(ctx,`INSERT INTO fleet_command_admissions(node_id,idempotency_key,request_digest,intent_id,effect_id,created_at) VALUES(?,?,?,?,?,?) ON CONFLICT DO NOTHING`,intent.NodeID,intent.IdempotencyKey,requestDigest,intent.ID,intent.EffectID,s.clock().UTC());if err!=nil{return federation.Intent{},false,err};inserted,err:=result.RowsAffected();if err!=nil{return federation.Intent{},false,err};if inserted==0{var storedDigest string;var storedIntentID federation.ID;if err=tx.QueryRowContext(ctx,`SELECT request_digest,intent_id FROM fleet_command_admissions WHERE node_id=? AND idempotency_key=?`,intent.NodeID,intent.IdempotencyKey).Scan(&storedDigest,&storedIntentID);errors.Is(err,sql.ErrNoRows){return federation.Intent{},false,ErrConflict};if err!=nil{return federation.Intent{},false,err};if storedDigest!=requestDigest{return federation.Intent{},false,ErrConflict};var storedRaw []byte;if err=tx.QueryRowContext(ctx,`SELECT intent_json FROM fleet_intents WHERE id=? AND node_id=?`,storedIntentID,intent.NodeID).Scan(&storedRaw);errors.Is(err,sql.ErrNoRows){return federation.Intent{},false,ErrConflict};if err!=nil{return federation.Intent{},false,err};var stored federation.Intent;if err=json.Unmarshal(storedRaw,&stored);err!=nil{return federation.Intent{},false,err};return stored,false,tx.Commit()};now:=s.clock().UTC();_,err=tx.ExecContext(ctx,`INSERT INTO fleet_intents VALUES(?,?,?,?,?,?,?,?,?,?)`,intent.ID,intent.NodeID,owner,"queued",priority,raw,[]byte(`{}`),now,now,intent.ExpiresAt);if err!=nil{return federation.Intent{},false,err};if err=tx.Commit();err!=nil{return federation.Intent{},false,err};return intent,true,nil}
func(s *Store)QueuedIntents(ctx context.Context,node federation.ID,limit uint32)([]federation.Intent,error){if limit==0||limit>500{limit=100};rows,err:=s.db.QueryContext(ctx,`SELECT intent_json FROM fleet_intents WHERE node_id=? AND status IN ('queued','sent') AND expires_at>? ORDER BY priority DESC,created_at LIMIT ?`,node,s.clock().UTC(),limit);if err!=nil{return nil,err};defer rows.Close();var out []federation.Intent;for rows.Next(){var raw []byte;if err=rows.Scan(&raw);err!=nil{return nil,err};var intent federation.Intent;if err=json.Unmarshal(raw,&intent);err!=nil{return nil,err};out=append(out,intent)};return out,rows.Err()}
func(s *Store)MarkIntentSent(ctx context.Context,id federation.ID)error{result,err:=s.db.ExecContext(ctx,`UPDATE fleet_intents SET status='sent',updated_at=? WHERE id=? AND status IN ('queued','sent')`,s.clock().UTC(),id);if err!=nil{return err};rows,err:=result.RowsAffected();if err!=nil||rows!=1{return ErrConflict};return nil}
func(s *Store)Receipt(ctx context.Context,receipt federation.Receipt)(bool,error){if s==nil||ctx==nil{return false,ErrInvalid};raw,err:=json.Marshal(receipt);if err!=nil{return false,err};receiptDigest:=digest(raw);tx,err:=s.db.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{return false,err};defer tx.Rollback();var rawIntent,currentRaw []byte;var current string;if err=tx.QueryRowContext(ctx,`SELECT intent_json,status,receipt_json FROM fleet_intents WHERE id=?`,receipt.IntentID).Scan(&rawIntent,&current,&currentRaw);errors.Is(err,sql.ErrNoRows){return false,ErrNotFound};if err!=nil{return false,err};var intent federation.Intent;if err=json.Unmarshal(rawIntent,&intent);err!=nil{return false,err};if receipt.NodeID!=intent.NodeID||receipt.EffectID!=intent.EffectID||receipt.IdempotencyKey!=intent.IdempotencyKey{return false,ErrConflict};result,err:=tx.ExecContext(ctx,`INSERT INTO fleet_receipt_replays(node_id,receipt_digest,intent_id,signature_key_id,received_at) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING`,receipt.NodeID,receiptDigest,receipt.IntentID,receipt.SignatureKeyID,s.clock().UTC());if err!=nil{return false,err};inserted,err:=result.RowsAffected();if err!=nil{return false,err};if inserted==0{var storedIntent federation.ID;var storedKey string;if err=tx.QueryRowContext(ctx,`SELECT intent_id,signature_key_id FROM fleet_receipt_replays WHERE node_id=? AND receipt_digest=?`,receipt.NodeID,receiptDigest).Scan(&storedIntent,&storedKey);err!=nil{return false,err};if storedIntent!=receipt.IntentID||storedKey!=receipt.SignatureKeyID{return false,ErrConflict};return true,tx.Commit()};if len(currentRaw)>0&&!bytes.Equal(currentRaw,[]byte(`{}`)){var previous federation.Receipt;if err=json.Unmarshal(currentRaw,&previous);err!=nil{return false,err};if receipt.UpdatedAt.Before(previous.UpdatedAt)||receipt.UpdatedAt.Equal(previous.UpdatedAt)&&sameReceiptEvidence(previous,receipt){return true,tx.Commit()};if !validReceiptTransition(previous.Status,receipt.Status){return false,ErrConflict}};if current==string(federation.IntentApplied)||current==string(federation.IntentRejected)||current==string(federation.IntentExpired){return false,ErrConflict};result,err=tx.ExecContext(ctx,`UPDATE fleet_intents SET status=?,receipt_json=?,updated_at=? WHERE id=? AND status IN ('queued','sent','accepted','running','ambiguous')`,receipt.Status,raw,s.clock().UTC(),receipt.IntentID);if err!=nil{return false,err};rows,err:=result.RowsAffected();if err!=nil||rows!=1{return false,ErrConflict};if err=tx.Commit();err!=nil{return false,err};return false,nil}
func(s *Store)PutRevocation(ctx context.Context,value federation.Revocation)error{raw,_:=json.Marshal(value);_,err:=s.db.ExecContext(ctx,`INSERT INTO fleet_revocations(node_id,authority_epoch,status,revocation_json,created_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(node_id,authority_epoch) DO UPDATE SET revocation_json=excluded.revocation_json,updated_at=excluded.updated_at WHERE fleet_revocations.status IN ('queued','sent')`,value.NodeID,value.NewAuthorityEpoch,"queued",raw,s.clock().UTC(),s.clock().UTC());return err}
func(s *Store)QueuedRevocations(ctx context.Context,node federation.ID,limit uint32)([]federation.Revocation,error){if limit==0||limit>100{limit=20};rows,err:=s.db.QueryContext(ctx,`SELECT revocation_json FROM fleet_revocations WHERE node_id=? AND status IN ('queued','sent') ORDER BY authority_epoch LIMIT ?`,node,limit);if err!=nil{return nil,err};defer rows.Close();var out []federation.Revocation;for rows.Next(){var raw []byte;if err=rows.Scan(&raw);err!=nil{return nil,err};var value federation.Revocation;if err=json.Unmarshal(raw,&value);err!=nil{return nil,err};out=append(out,value)};return out,rows.Err()}
func(s *Store)MarkRevocationSent(ctx context.Context,node federation.ID,epoch uint64)error{result,err:=s.db.ExecContext(ctx,`UPDATE fleet_revocations SET status='sent',updated_at=? WHERE node_id=? AND authority_epoch=? AND status IN ('queued','sent')`,s.clock().UTC(),node,epoch);if err!=nil{return err};rows,err:=result.RowsAffected();if err!=nil||rows!=1{return ErrConflict};return nil}
func(s *Store)AckRevocation(ctx context.Context,node federation.ID,epoch uint64)error{tx,err:=s.db.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{return err};defer tx.Rollback();result,err:=tx.ExecContext(ctx,`UPDATE fleet_revocations SET status='applied',updated_at=? WHERE node_id=? AND authority_epoch=? AND status IN ('queued','sent')`,s.clock().UTC(),node,epoch);if err!=nil{return err};rows,err:=result.RowsAffected();if err!=nil||rows!=1{return ErrConflict};result,err=tx.ExecContext(ctx,`UPDATE fleet_nodes SET state='revoked',updated_at=? WHERE id=? AND authority_epoch=? AND state='revoking'`,s.clock().UTC(),node,epoch);if err!=nil{return err};rows,err=result.RowsAffected();if err!=nil||rows!=1{return ErrConflict};return tx.Commit()}
type EventApplyResult struct{AckThrough,ExpectedSequence,ReceivedSequence,SnapshotGeneration uint64;Resync bool}
func(s *Store)ApplyEvents(ctx context.Context,nodeID federation.ID,events []federation.NodeEvent)(EventApplyResult,error){if s==nil||ctx==nil||!nodeID.Valid()||len(events)==0{return EventApplyResult{},ErrInvalid};tx,err:=s.db.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{return EventApplyResult{},err};defer tx.Rollback();node,err:=loadNodeTx(ctx,tx,nodeID);if err!=nil{return EventApplyResult{},err};cursor:=node.ProjectionSequence;expected:=cursor+1;for _,event:=range events{if event.Sequence<=cursor{var storedRaw []byte;if err=tx.QueryRowContext(ctx,`SELECT event_json FROM fleet_events WHERE node_id=? AND sequence=?`,nodeID,event.Sequence).Scan(&storedRaw);errors.Is(err,sql.ErrNoRows){return EventApplyResult{},ErrConflict};if err!=nil{return EventApplyResult{},err};var stored federation.NodeEvent;if err=json.Unmarshal(storedRaw,&stored);err!=nil||!sameNodeEvent(stored,event){return EventApplyResult{},ErrConflict};continue};if event.Sequence!=expected{now:=s.clock().UTC();if _,err=tx.ExecContext(ctx,`UPDATE fleet_projections SET stale=1 WHERE node_id=?`,nodeID);err!=nil{return EventApplyResult{},err};if _,err=tx.ExecContext(ctx,`UPDATE fleet_nodes SET state='degraded',last_seen_at=?,updated_at=? WHERE id=? AND state NOT IN ('revoking','revoked')`,now,now,nodeID);err!=nil{return EventApplyResult{},err};if err=tx.Commit();err!=nil{return EventApplyResult{},err};return EventApplyResult{AckThrough:cursor,ExpectedSequence:expected,ReceivedSequence:event.Sequence,SnapshotGeneration:node.SnapshotGeneration,Resync:true},nil};expected++};last:=cursor;for _,event:=range events{if event.Sequence<=cursor{last=event.Sequence;continue};raw,marshalErr:=json.Marshal(event);if marshalErr!=nil{return EventApplyResult{},marshalErr};if _,err=tx.ExecContext(ctx,`INSERT INTO fleet_events VALUES(?,?,?,?,?)`,nodeID,event.Sequence,event.ID,raw,event.OccurredAt);err!=nil{return EventApplyResult{},err};if event.ResourceKind!=""&&event.ResourceID!=""{_,err=tx.ExecContext(ctx,`INSERT INTO fleet_projections VALUES(?,?,?,?,?,?,?,?,?,0) ON CONFLICT(node_id,resource_kind,resource_id) DO UPDATE SET tenant_id=excluded.tenant_id,generation=excluded.generation,status_json=excluded.status_json,digest=excluded.digest,observed_at=excluded.observed_at,event_sequence=excluded.event_sequence,stale=0 WHERE fleet_projections.generation<=excluded.generation`,nodeID,event.TenantID,event.ResourceKind,event.ResourceID,event.Generation,event.Payload,event.PayloadDigest,event.OccurredAt,event.Sequence);if err!=nil{return EventApplyResult{},err}};last=event.Sequence};if last>cursor{node.ProjectionSequence=last};now:=s.clock().UTC();if node.State==NodeDegraded{if _,err=tx.ExecContext(ctx,`UPDATE fleet_projections SET stale=1 WHERE node_id=?`,nodeID);err!=nil{return EventApplyResult{},err}};_,err=tx.ExecContext(ctx,`UPDATE fleet_nodes SET projection_sequence=?,last_seen_at=?,updated_at=? WHERE id=?`,node.ProjectionSequence,now,now,nodeID);if err!=nil{return EventApplyResult{},err};if err=tx.Commit();err!=nil{return EventApplyResult{},err};return EventApplyResult{AckThrough:events[len(events)-1].Sequence,ExpectedSequence:node.ProjectionSequence+1,SnapshotGeneration:node.SnapshotGeneration},nil}
func loadNodeTx(ctx context.Context,tx *sql.Tx,id federation.ID)(Node,error){var node Node;var raw []byte;err:=tx.QueryRowContext(ctx,`SELECT id,owner_tenant_id,name,state,authority_epoch,capabilities_json,projection_sequence,snapshot_generation,last_seen_at,created_at,updated_at,certificate_fingerprint FROM fleet_nodes WHERE id=?`,id).Scan(&node.ID,&node.OwnerTenantID,&node.Name,&node.State,&node.AuthorityEpoch,&raw,&node.ProjectionSequence,&node.SnapshotGeneration,&node.LastSeenAt,&node.CreatedAt,&node.UpdatedAt,&node.CertificateFingerprint);if errors.Is(err,sql.ErrNoRows){return node,ErrNotFound};if err!=nil{return node,err};err=json.Unmarshal(raw,&node.Capabilities);return node,err}
func(s *Store)MarkNodeStale(ctx context.Context,node federation.ID)error{_,err:=s.db.ExecContext(ctx,`UPDATE fleet_projections SET stale=1 WHERE node_id=?`,node);if err==nil{_,err=s.db.ExecContext(ctx,`UPDATE fleet_nodes SET state=CASE WHEN state IN ('revoking','revoked','degraded') THEN state ELSE 'offline' END,updated_at=? WHERE id=?`,s.clock().UTC(),node)};return err}
func(s *Store)PutSaga(ctx context.Context,saga Saga)error{raw,_:=json.Marshal(saga);_,err:=s.db.ExecContext(ctx,`INSERT INTO fleet_sagas VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET state=excluded.state,current_step=excluded.current_step,saga_json=excluded.saga_json,updated_at=excluded.updated_at,error_code=excluded.error_code`,saga.ID,saga.OwnerTenantID,saga.Kind,saga.State,saga.Current,raw,saga.CreatedAt,saga.UpdatedAt,saga.ErrorCode);return err}
func(s *Store)Saga(ctx context.Context,id federation.ID)(Saga,error){var saga Saga;var raw []byte;err:=s.db.QueryRowContext(ctx,`SELECT saga_json FROM fleet_sagas WHERE id=?`,id).Scan(&raw);if errors.Is(err,sql.ErrNoRows){return saga,ErrNotFound};if err!=nil{return saga,err};err=json.Unmarshal(raw,&saga);return saga,err}
func(s *Store)PutEncryptedSecret(ctx context.Context,value EncryptedSecret)error{raw,_:=json.Marshal(value);_,err:=s.db.ExecContext(ctx,`INSERT INTO fleet_encrypted_secrets VALUES(?,?,?,?,?,NULL)`,value.TargetNodeID,value.SecretID,value.Version,raw,value.ExpiresAt);return err}
func(s *Store)TakeEncryptedSecrets(ctx context.Context,node federation.ID,limit uint32)([]EncryptedSecret,error){if limit==0||limit>100{limit=20};rows,err:=s.db.QueryContext(ctx,`SELECT envelope_json FROM fleet_encrypted_secrets WHERE target_node_id=? AND consumed_at IS NULL AND expires_at>? ORDER BY secret_id,version LIMIT ?`,node,s.clock().UTC(),limit);if err!=nil{return nil,err};defer rows.Close();var out []EncryptedSecret;for rows.Next(){var raw []byte;if err=rows.Scan(&raw);err!=nil{return nil,err};var value EncryptedSecret;if err=json.Unmarshal(raw,&value);err!=nil{return nil,err};out=append(out,value)};return out,rows.Err()}
func validReceiptTransition(previous,next federation.IntentStatus)bool{if previous==next{return true};switch previous{case federation.IntentAccepted:return next==federation.IntentRunning||next==federation.IntentAmbiguous||next==federation.IntentApplied||next==federation.IntentRejected||next==federation.IntentExpired;case federation.IntentRunning:return next==federation.IntentAmbiguous||next==federation.IntentApplied||next==federation.IntentRejected;case federation.IntentAmbiguous:return next==federation.IntentRunning||next==federation.IntentApplied||next==federation.IntentRejected};return false}
func sameReceiptEvidence(left,right federation.Receipt)bool{left.SignatureKeyID="";left.Signature=nil;right.SignatureKeyID="";right.Signature=nil;leftRaw,leftErr:=json.Marshal(left);rightRaw,rightErr:=json.Marshal(right);return leftErr==nil&&rightErr==nil&&bytes.Equal(leftRaw,rightRaw)}
func sameNodeEvent(left,right federation.NodeEvent)bool{left.SignatureKeyID="";left.Signature=nil;right.SignatureKeyID="";right.Signature=nil;leftRaw,leftErr:=json.Marshal(left);rightRaw,rightErr:=json.Marshal(right);return leftErr==nil&&rightErr==nil&&bytes.Equal(leftRaw,rightRaw)}
